```java
public final class Solution {
    private Solution() {}

    public static String[] describeChanges(String[] names, String[] before,
                                           String[] after) {
        if (names == null || before == null || after == null
                || names.length != before.length || before.length != after.length) {
            throw new IllegalArgumentException("Mismatched arrays");
        }
        java.util.ArrayList<String> changes = new java.util.ArrayList<>();
        for (int i = 0; i < names.length; i++) {
            if (names[i] == null || names[i].trim().isEmpty()) {
                throw new IllegalArgumentException("Blank property name");
            }
            if (before[i] != after[i]) {
                changes.add(names[i] + " := " + String.valueOf(after[i]));
            }
        }
        return changes.toArray(new String[0]);
    }
}
```

