import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        String[] names = {"title", "owner", "note", "count"};
        String[] before = {new String("same"), null, "old", "1"};
        String[] after = {new String("same"), "Ada", null, "2"};
        String[] result = Solution.describeChanges(names, before, after);
        assertArrayEquals(new String[]{"owner := Ada", "note := null", "count := 2"},
                result, "changes use value equality and preserve order");
        assertArrayEquals(new String[]{"title", "owner", "note", "count"}, names,
                "names not mutated");
        assertTrue(before[0].equals("same") && before[1] == null && before[2].equals("old"),
                "before not mutated");
        assertTrue(after[0].equals("same") && after[2] == null, "after not mutated");

        assertEquals(0, Solution.describeChanges(new String[0], new String[0], new String[0]).length,
                "empty arrays");
        assertEquals(0, Solution.describeChanges(new String[]{"p"}, new String[]{null},
                new String[]{null}).length, "equal null values unchanged");
        assertArrayEquals(new String[]{" exact name  := new"},
                Solution.describeChanges(new String[]{" exact name "}, new String[]{"old"},
                        new String[]{"new"}), "valid name is preserved exactly");

        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(null, new String[0], new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[0], null, new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[0], new String[0], null));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[]{"x"}, new String[0], new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[]{"x"}, new String[]{"a"}, new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[]{null}, new String[]{"a"}, new String[]{"b"}));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[]{" \t"}, new String[]{"a"}, new String[]{"b"}));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.describeChanges(new String[]{"valid", ""},
                        new String[]{"a", "b"}, new String[]{"a", "b"}));
    }

    private static void assertArrayEquals(String[] expected, String[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected=" + Arrays.toString(expected)
                    + ", actual=" + Arrays.toString(actual));
        }
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) throw new AssertionError(message);
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectThrows(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw new AssertionError("Expected " + type.getName() + " but got " + error, error);
        }
        throw new AssertionError("Expected " + type.getName() + " to be thrown");
    }
}

